mapper.select:
SELECT category_id
FROM shop
WHERE id = #{shopId}
  AND region = #{region}
  AND is_deleted = FALSE

SELECT category_id AS categoryId,
       SUM(weight) AS affinity
FROM user_behavior_event
WHERE user_id = #{userId}
  AND region = #{region}
  AND category_id IS NOT NULL
GROUP BY category_id
ORDER BY affinity DESC, category_id ASC
LIMIT #{limit}

SELECT s.id, s.merchant_id, s.category_id, s.name, s.cover_url, s.score, s.price_per_capita, s.currency, s.address, s.latitude, s.longitude, a.name AS area_name, c.name AS city_name, s.has_deal, s.open_now, s.tags, COALESCE(v.view_count, 0) AS view_count FROM shop s JOIN area a ON a.id = s.area_id AND a.region = s.region AND a.status = 1 JOIN city c ON c.id = s.city_id AND c.region = s.region AND c.status = 1 JOIN category cat ON cat.id = s.category_id AND cat.region = s.region AND cat.status = 1 LEFT JOIN ( SELECT shop_id, SUM(view_count) AS view_count FROM shop_view_daily GROUP BY shop_id ) v ON v.shop_id = s.id WHERE s.region = #{region} AND s.status = 1 AND s.is_deleted = FALSE
AND s.city_id = #{cityId}
AND s.id != #{excludeShopId}
AND s.category_id IN #{cid}
ORDER BY COALESCE(v.view_count, 0) DESC, s.score DESC, s.id ASC LIMIT #{limit}
